package com.arjunren.loan.config;
import com.arjunren.loan.domain.Role; import com.arjunren.loan.entity.AppUser; import com.arjunren.loan.repository.UserRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Profile; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component;
@Component@Profile("dev")public class DevDataSeeder implements CommandLineRunner{private final UserRepository users;private final PasswordEncoder encoder;public DevDataSeeder(UserRepository u,PasswordEncoder e){users=u;encoder=e;}public void run(String...args){seed("admin@example.com","Development Admin","AdminPassword123!",Role.ADMIN);seed("officer@example.com","Development Officer","OfficerPassword123!",Role.LOAN_OFFICER);seed("customer@example.com","Development Customer","CustomerPassword123!",Role.CUSTOMER);}private void seed(String email,String name,String pass,Role role){if(users.findByEmailIgnoreCase(email).isEmpty())users.save(new AppUser(email,encoder.encode(pass),name,role));}}

